export const EXTRA_MOTIFS = Object.keys(EXTRA);

export function extraMotif(motif: string, p: CoverPalette): string | null {
  const svg = EXTRA[motif];
  if (!svg) return null;
  return svg.split('@L@').join(p.line).split('@S@').join(p.soft).split('@B@').join(p.bg);
}
